weak_tls_versions := {"SSLv2", "SSLv3", "TLSv1.0", "TLSv1.1", "TLS1.0", "TLS1.1"}
weak_cipher_patterns := {"_RSA_WITH_", "_CBC_", "TLS_RSA_", "WITH_DES_", "WITH_3DES_", "WITH_RC4_", "WITH_NULL_", "anon", "EXPORT", "NULL", "eNULL", "aNULL"}
weak_hash_in_cipher := {"MD5", "SHA1", "SHA_1", "SHA-1"}
min_rsa_size := 2048
min_symmetric_size := 128

algorithm_keywords := {"algorithm", "cipher", "crypto", "encryption", "type", "name", "specification", "provider", "engine", "module", "hash"}
key_size_keywords := {"key_size", "key_length", "bits", "size", "length", "modulus_size"}
tls_version_keywords := {"tls_version", "ssl_version", "min_version", "protocol_version", "ssl_policy", "security_policy", "enabled_protocols", "supported_versions", "version"}
kdf_keywords := {"kdf", "pbkdf2", "bcrypt", "scrypt", "argon2", "iterations", "rounds", "cost", "work_factor"}
encrypt_attr_names := {"encrypt", "encryption", "hash", "digest", "checksum"}

contains_weak_algorithm(value) {
    upper(value) == weak_algorithms[_]
}

contains_weak_algorithm(value) {
    regex.match("(?i)(DES|3DES|RC2|RC4|Blowfish|ECB|MD5|SHA1|SHA-1)", value)
}

contains_weak_cipher(value) {
    regex.match("(?i)(_,.*RSA.*_|CBC|_DES|_3DES|_RC4|_NULL|EXPORT|anon)", value)
}

contains_weak_cipher(value) {
    weak_cipher_patterns[_] = pattern
    regex.match(pattern, value)
}

is_weak_tls_version(value) {
    lower(value) == lower(weak_tls_versions[_])
}

walk_nodes(node, callback) {
    walk(node, [_, n])
    callback(n)
}

check_function_call_for_weak_crypto(node) {
    node.ir_type == "FunctionCall"
    node.name == "filter|hash"
    arg := node.args[_]
    arg.ir_type == "String"
    upper(arg.value) == weak_algorithms[_]
}

